type LocaleContextValue = {
  locale: WireLocale;
  setLocale: (locale: WireLocale) => void;
  t: (key: string, values?: Record<string, string | number>) => string;
};

const LocaleContext = createContext<LocaleContextValue | null>(null);

export function LocaleProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocale] = useState<WireLocale>('es');

  useEffect(() => {
    try {
      const savedLocale = window.localStorage.getItem(STORAGE_KEY);
      if (savedLocale === 'es' || savedLocale === 'en') setLocale(savedLocale);
    } catch {
      // Keep the default language when browser storage is unavailable.
    }
  }, []);

  const updateLocale = useCallback((nextLocale: WireLocale) => {
    try {
      window.localStorage.setItem(STORAGE_KEY, nextLocale);
    } catch {
      // The language can still change for the current session.
    }
    document.documentElement.lang = nextLocale;
    setLocale(nextLocale);
  }, []);

  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  const value = useMemo<LocaleContextValue>(() => ({
    locale,
    setLocale: updateLocale,
    t: (key, values) => {
      const message = messages[locale][key] ?? messages.es[key] ?? key;
      return Object.entries(values ?? {}).reduce(
        (result, [name, value]) => result.split(`{${name}}`).join(String(value)),
        message,
      );
    },
  }), [locale, updateLocale]);

  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useWireLocale() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error('useWireLocale must be used inside LocaleProvider');
  return context;
}
